#include <iomanip>
#include <iostream>
#include <limits>

bool truncar_a_ll(double dato, long long& destino) {
    if (!std::isfinite(dato)) {
        return false;
    }

    const double truncado = std::trunc(dato);
    // Este inicio solo admite un truncado igual a cero.
    if (truncado != 0.0) {
        return false;
    }
    destino = 0;
    return true;
}

int main() {
    if (std::numeric_limits<long long>::radix != 2
        || std::numeric_limits<long long>::digits != 63
        || std::numeric_limits<double>::radix != 2
        || std::numeric_limits<double>::digits != 53) {
        return 2;
    }

    int caso = 0;
    if (!(std::cin >> caso)) {
        return 1;
    }

    const double minimo =
        static_cast<double>(std::numeric_limits<long long>::lowest());
    const double superior = -minimo;
    double dato = 0.0;
    switch (caso) {
    case 1:
        dato = minimo;
        break;
    case 2:
        dato = superior;
        break;
    case 3:
        dato = std::nextafter(superior, 0.0);
        break;
    case 4:
        dato = std::nextafter(minimo, std::numeric_limits<double>::lowest());
        break;
    case 5:
        dato = 9223372036854775807.0;
        break;
    case 6:
        dato = -3.75;
        break;
    case 7:
        dato = -0.75;
        break;
    case 8:
        dato = 0.0;
        break;
    case 9:
        dato = std::numeric_limits<double>::infinity();
        break;
    case 10:
        dato = std::numeric_limits<double>::quiet_NaN();
        break;
    case 11:
        dato = -std::numeric_limits<double>::infinity();
        break;
    default:
        return 1;
    }

    long long destino = 17;
    const bool aceptado = truncar_a_ll(dato, destino);
    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Destino=" << destino << '\n';
    return 0;
}

