        || std::numeric_limits<long long>::digits != 63
        || std::numeric_limits<double>::radix != 2
        || std::numeric_limits<double>::digits != 53) {
        return 2;
    }

    const double minimo =
        static_cast<double>(std::numeric_limits<long long>::lowest());
    const double superior = -minimo;
